-- V104 access recertification evidence. Decisions do not automatically mutate membership.
CREATE TABLE IF NOT EXISTS access_review_campaigns(tenant_id text NOT NULL,id text NOT NULL,campaign_key text NOT NULL,status text NOT NULL CHECK(status IN ('OPEN','CLOSED')),snapshot_hash char(64) NOT NULL CHECK(snapshot_hash ~ '^[a-f0-9]{64}$'),item_count integer NOT NULL CHECK(item_count BETWEEN 1 AND 100000),created_by_hash char(64) NOT NULL,reviewer_hash char(64) NOT NULL,created_at timestamptz NOT NULL,closed_at timestamptz,summary_hash char(64),PRIMARY KEY(tenant_id,id));
CREATE TABLE IF NOT EXISTS access_review_decisions(tenant_id text NOT NULL,campaign_id text NOT NULL,item_hash char(64) NOT NULL CHECK(item_hash ~ '^[a-f0-9]{64}$'),outcome text NOT NULL CHECK(outcome IN ('RETAIN','REVOKE')),evidence_hash char(64) NOT NULL CHECK(evidence_hash ~ '^[a-f0-9]{64}$'),reviewer_hash char(64) NOT NULL,decided_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,campaign_id,item_hash),FOREIGN KEY(tenant_id,campaign_id) REFERENCES access_review_campaigns(tenant_id,id));
CREATE TABLE IF NOT EXISTS access_review_events(seq bigserial PRIMARY KEY,id text UNIQUE NOT NULL,tenant_id text NOT NULL,campaign_id text NOT NULL,event_type text NOT NULL,actor_hash char(64) NOT NULL,trace_hash char(64) NOT NULL,evidence_json jsonb NOT NULL,occurred_at timestamptz NOT NULL,FOREIGN KEY(tenant_id,campaign_id) REFERENCES access_review_campaigns(tenant_id,id));
ALTER TABLE access_review_campaigns ENABLE ROW LEVEL SECURITY;ALTER TABLE access_review_campaigns FORCE ROW LEVEL SECURITY;ALTER TABLE access_review_decisions ENABLE ROW LEVEL SECURITY;ALTER TABLE access_review_decisions FORCE ROW LEVEL SECURITY;ALTER TABLE access_review_events ENABLE ROW LEVEL SECURITY;ALTER TABLE access_review_events FORCE ROW LEVEL SECURITY;
CREATE POLICY access_review_campaign_tenant ON access_review_campaigns USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY access_review_decision_tenant ON access_review_decisions USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY access_review_event_tenant ON access_review_events USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE OR REPLACE FUNCTION deny_access_review_evidence_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'access review evidence is append only'; END $$;CREATE TRIGGER access_review_decisions_append_only BEFORE UPDATE OR DELETE ON access_review_decisions FOR EACH ROW EXECUTE FUNCTION deny_access_review_evidence_mutation();CREATE TRIGGER access_review_events_append_only BEFORE UPDATE OR DELETE ON access_review_events FOR EACH ROW EXECUTE FUNCTION deny_access_review_evidence_mutation();
